const page=document.body.dataset.page;
async function start(){try{const response=await fetch('/api/auth/me',{credentials:'same-origin',cache:'no-store'});if(!response.ok){location.replace('login.html?next='+encodeURIComponent(location.pathname+location.search));return}const {user}=await response.json();window.CampusSession=user;const workspaceResponse=await fetch('/api/workspace',{credentials:'same-origin',cache:'no-store'});if(!workspaceResponse.ok)throw Error('Workspace unavailable');window.CampusWorkspace=(await workspaceResponse.json()).workspace;await import('./pages/'+page+'.js')}catch{document.body.innerHTML='<div class="connection-error"><h1>Could not connect.</h1><p>Keep the Campus server running, then refresh this page.</p><button type="button" id="retry-connection">Try again</button></div>';document.querySelector('#retry-connection').onclick=()=>location.reload()}}
window.addEventListener('pageshow',event=>{if(event.persisted)location.reload()});window.addEventListener('storage',event=>{if(event.key==='campus-signout')location.replace('login.html')});
start();
